// ── Chat entry types ──────────────────────────────────────────────────

/// Current time as Unix epoch milliseconds.
fn now_ms() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as i64
}

/// Human-readable remaining tunnel lifetime, e.g. "38 minutes remaining".
fn tunnel_remaining_label(expires_at_ms: u64) -> String {
    let remaining = expires_at_ms.saturating_sub(now_ms() as u64);
    if remaining >= 24 * 60 * 60 * 1_000 {
        format!("{} days remaining", remaining / (24 * 60 * 60 * 1_000))
    } else if remaining >= 60 * 60 * 1_000 {
        format!("{} hours remaining", remaining / (60 * 60 * 1_000))
    } else if remaining >= 60 * 1_000 {
        format!("{} minutes remaining", remaining / (60 * 1_000))
    } else if remaining > 0 {
        "less than a minute remaining".to_string()
    } else {
        "Expired".to_string()
    }
}

/// Render a tunnel target's TCP host:port in user-friendly form, using
/// `localhost` when the target is loopback.
fn tunnel_target_label(host: std::net::IpAddr, port: u16) -> String {
    if host.is_loopback() {
        format!("localhost:{port}")
    } else {
        format!("{host}:{port}")
    }
}

/// Format a connected received-tunnel loopback address for display.
///
/// Only an explicitly HTTP-identified service gets the `http://` scheme
/// prefix; other TCP services are shown as a bare host:port.
fn tunnel_local_address(
    offer: &boru_core::tunnel::TunnelOffer,
    addr: std::net::SocketAddr,
) -> String {
    if offer.is_http {
        format!("http://{addr}")
    } else {
        addr.to_string()
    }
}

/// Human-readable tunnel expiry countdown, e.g. "Expires in 42 minutes".
fn tunnel_expiry_label(expires_at_ms: u64) -> String {
    let remaining = expires_at_ms.saturating_sub(now_ms() as u64);
    if remaining >= 24 * 60 * 60 * 1_000 {
        format!("Expires in {} days", remaining / (24 * 60 * 60 * 1_000))
    } else if remaining >= 60 * 60 * 1_000 {
        format!("Expires in {} hours", remaining / (60 * 60 * 1_000))
    } else if remaining >= 60 * 1_000 {
        format!("Expires in {} minutes", remaining / (60 * 1_000))
    } else if remaining > 0 {
        "Expires in less than a minute".to_string()
    } else {
        "Expired".to_string()
    }
}

/// A peer is considered Away when no presence/activity has refreshed its
/// last-seen timestamp for this long (10 seconds).
const AWAY_THRESHOLD_MS: u64 = 10_000;

/// Human-readable connection route label from Iroh path data.
///
/// The backend only records what Iroh reliably reports; unknown routes map to
/// the neutral "Connected" label rather than inventing a Direct/Relay guess.
fn tunnel_route_label(route: boru_core::tunnel::service::TunnelRoute) -> &'static str {
    route.label()
}

/// Human-readable transfer summary for a tunnel, e.g. "12.4 MB transferred".
fn tunnel_transfer_label(info: boru_core::tunnel::service::TunnelConnectionInfo) -> Option<String> {
    let total = info.bytes_sent.saturating_add(info.bytes_received);
    if total == 0 {
        None
    } else {
        Some(format!("{} transferred", format_file_size(total)))
    }
}

/// Human-readable connection duration for a tunnel, e.g. "3m 12s".
fn tunnel_duration_label(connected_at_ms: u64) -> Option<String> {
    if connected_at_ms == 0 {
        return None;
    }
    let elapsed_ms = (now_ms() as u64).saturating_sub(connected_at_ms);
    let seconds = elapsed_ms / 1_000;
    if seconds == 0 {
        return Some("connected just now".to_string());
    }
    if seconds < 60 {
        return Some(format!("{seconds}s"));
    }
    let minutes = seconds / 60;
    if minutes < 60 {
        return Some(format!("{minutes}m {}s", seconds % 60));
    }
    let hours = minutes / 60;
    Some(format!("{hours}h {}m", minutes % 60))
}

/// Compact one-line connection info for a tunnel row, e.g.
/// "Direct · 12.4 MB transferred · 3m 12s". Metrics are only included when
/// available; the route label is always shown once a connection exists.
fn tunnel_connection_info_label(info: boru_core::tunnel::service::TunnelConnectionInfo) -> String {
    let mut parts = vec![tunnel_route_label(info.route).to_string()];
    if let Some(transfer) = tunnel_transfer_label(info) {
        parts.push(transfer);
    }
    if let Some(duration) = tunnel_duration_label(info.connected_at_ms) {
        parts.push(duration);
    }
    parts.join("  ·  ")
}

/// Human-readable tunnel status for the GUI, mapping backend states to
/// user-friendly labels: "Available", "Connecting", "Connected", "Failed",
/// "Disconnected", "Expired", "Revoked".
fn tunnel_status_label(def: &boru_core::tunnel::service::TunnelDefinition) -> &'static str {
    let now = now_ms().max(0) as u64;
    // Expired tunnels (past their expiry) show as Expired regardless of
    // their lifecycle state, unless they were already revoked.
    if def.status != boru_core::tunnel::service::TunnelStatus::Revoked && def.expires_at_ms <= now {
        return "Expired";
    }
    def.status.label()
}

/// Return a themed color for a tunnel status badge.
fn tunnel_status_color(
    theme: &iced::Theme,
    def: &boru_core::tunnel::service::TunnelDefinition,
) -> iced::Color {
    use boru_core::tunnel::service::{TunnelDefinition, TunnelStatus};
    let now = now_ms().max(0) as u64;
    if def.status != TunnelStatus::Revoked && def.expires_at_ms <= now {
        return text_muted(theme);
    }
    match def.status {
        TunnelStatus::Active => accent_primary(theme),
        TunnelStatus::Connecting => color_warning(theme),
        TunnelStatus::Connected => accent_green(theme),
        TunnelStatus::Revoked => text_muted(theme),
        TunnelStatus::Failed => color_error(theme),
        TunnelStatus::Disconnected => text_muted(theme),
    }
}

/// Presence state shown in contact displays.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum PeerPresence {
    Online,
    Away,
    Offline,
    /// The peer is known but we have not yet established a live connection
    /// (e.g. the room subscription is still in flight).
    Connecting,
    /// We cannot determine the peer's state (no identity, no presence data).
    Unknown,
}

impl PeerPresence {
    fn label(&self) -> &'static str {
        match self {
            PeerPresence::Online => "Online",
            PeerPresence::Away => "Away",
            PeerPresence::Offline => "Offline",
            PeerPresence::Connecting => "Connecting…",
            PeerPresence::Unknown => "Unknown",
        }
    }

    fn color(&self, theme: &iced::Theme) -> Color {
        match self {
            PeerPresence::Online => accent_green(theme),
            PeerPresence::Away | PeerPresence::Connecting => color_warning(theme),
            PeerPresence::Offline | PeerPresence::Unknown => text_muted(theme),
        }
    }

    fn icon(&self) -> &'static [u8] {
        match self {
            PeerPresence::Online | PeerPresence::Away => ICON_ONLINE,
            PeerPresence::Connecting => ICON_RETRY,
            PeerPresence::Offline | PeerPresence::Unknown => ICON_OFFLINE,
        }
    }
}

// ── Home connection hero state (UI-08) ────────────────────────────────
//
// The home hero card is bound to real readiness/connection state.  Visual
// variants map 1:1 from the existing application state semantics below —
// the UI never invents a state that the network layer has not reported.
//
// Mapping (priority order, most severe first):
//   1. `MeshHealth::Offline(_)`            -> Offline   (red)
//   2. `MeshHealth::Degraded(_)`           -> Degraded  (amber)
//   3. has_peer_connections                -> Ready     (green)
//   4. relay reachable (sender present)    -> Connecting (waiting for peers)
//   5. otherwise                           -> Starting  (bootstrap)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum HomeConnectionVariant {
    /// Boru is still booting its network stack; no sender or peers yet.
    Starting,
    /// The relay / gossip sender is up but no peer connections yet.
    Connecting,
    /// Peer connections exist and the mesh is healthy.
    Ready,
    /// Connected but the mesh reports degradation.
    Degraded,
    /// Transport is offline (mesh health Offline).
    Offline,
}

/// Truthful mapping from application connection state to the home hero
/// variant.  This is a pure function so it can be unit-tested in isolation.
fn home_connection_variant(
    mesh_health: &MeshHealth,
    has_peer_connections: bool,
    relay_reachable: bool,
) -> HomeConnectionVariant {
    match mesh_health {
        MeshHealth::Offline(_) => HomeConnectionVariant::Offline,
        MeshHealth::Degraded(_) => HomeConnectionVariant::Degraded,
        MeshHealth::Good => {
            if has_peer_connections {
                HomeConnectionVariant::Ready
            } else if relay_reachable {
                HomeConnectionVariant::Connecting
            } else {
                HomeConnectionVariant::Starting
            }
        }
    }
}

/// A bounded, presentation-ready mesh event with a real capture time.
#[derive(Debug, Clone)]
struct MeshEvent {
    message: String,
    recorded_at: Instant,
}

/// UI-28: true when a mesh event log line is a transient startup/connecting
/// status that should be dropped once the mesh reaches `MeshHealth::Good`.
/// Real lifecycle events (degraded/offline/recovered transitions, errors,
/// discovery summaries) are preserved.
fn is_transient_mesh_event(message: &str) -> bool {
    let lower = message.to_ascii_lowercase();
    lower.contains("starting up")
        || lower.contains("connecting to lobby")
        || lower.contains("connected to lobby")
        || lower.contains("subscribing to")
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ChatKind {
    System,
    Local,
    Remote,
}

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
pub(crate) enum InlinePlaybackErrorKind {
    UnsupportedCodec,
    CorruptFile,
    MissingFile,
    PermissionDenied,
    Initialization,
    Unknown,
}

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
pub(crate) struct InlinePlaybackError {
    pub(crate) kind: InlinePlaybackErrorKind,
    /// Short backend detail retained for diagnostics; never shown as a path.
    pub(crate) detail: String,
}

impl InlinePlaybackError {
    pub(crate) fn from_backend(error: impl Into<String>) -> Self {
        let raw_detail = error.into();
        let lower = raw_detail.to_ascii_lowercase();
        let kind = if lower.contains("codec")
            || lower.contains("decoder")
            || lower.contains("not-negotiated")
            || lower.contains("cannot decode")
        {
            InlinePlaybackErrorKind::UnsupportedCodec
        } else if lower.contains("not found")
            || lower.contains("missing")
            || lower.contains("no such file")
        {
            InlinePlaybackErrorKind::MissingFile
        } else if lower.contains("permission") || lower.contains("access denied") {
            InlinePlaybackErrorKind::PermissionDenied
        } else if lower.contains("corrupt")
            || lower.contains("invalid")
            || lower.contains("parse")
            || lower.contains("malformed")
        {
            InlinePlaybackErrorKind::CorruptFile
        } else if lower.contains("init")
            || lower.contains("construct")
            || lower.contains("open")
            || lower.contains("resource")
        {
            InlinePlaybackErrorKind::Initialization
        } else {
            InlinePlaybackErrorKind::Unknown
        };
        // Backend messages can contain local paths or peer-controlled names.
        // Keep a bounded diagnostic without carrying those values into logs.
        let detail = raw_detail
            .split_whitespace()
            .map(|token| {
                if token.contains('/') || token.contains('\\') {
                    "<path>"
                } else {
                    token
                }
            })
            .collect::<Vec<_>>()
            .join(" ");
        Self {
            kind,
            detail: detail.chars().take(240).collect(),
        }
    }

    pub(crate) fn title(&self) -> &'static str {
        match self.kind {
            InlinePlaybackErrorKind::UnsupportedCodec => "Video format not supported",
            InlinePlaybackErrorKind::CorruptFile => "Video file appears damaged",
            InlinePlaybackErrorKind::MissingFile => "Video file is missing",
            InlinePlaybackErrorKind::PermissionDenied => "Video cannot be opened",
            InlinePlaybackErrorKind::Initialization => "Video player could not start",
            InlinePlaybackErrorKind::Unknown => "Video playback failed",
        }
    }

    pub(crate) fn message(&self) -> &'static str {
        match self.kind {
            InlinePlaybackErrorKind::UnsupportedCodec => {
                "This packaged player cannot decode this video's format."
            }
            InlinePlaybackErrorKind::CorruptFile => "The attachment is not a valid playable video.",
            InlinePlaybackErrorKind::MissingFile => {
                "The saved attachment is no longer on this device."
            }
            InlinePlaybackErrorKind::PermissionDenied => {
                "The saved attachment could not be accessed."
            }
            InlinePlaybackErrorKind::Initialization => {
                "Try again without downloading the attachment again."
            }
            InlinePlaybackErrorKind::Unknown => {
                "The attachment is still available for saving or opening externally."
            }
        }
    }

    pub(crate) fn retry_available(&self) -> bool {
        matches!(
            self.kind,
            InlinePlaybackErrorKind::Initialization | InlinePlaybackErrorKind::Unknown
        )
    }
}

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
pub(crate) enum DownloadFailure {
    PermissionDenied,
    FileRemoved,
    FileChanged {
        detail: Option<String>,
    },
    VersionMismatch {
        current_version: Option<u64>,
        detail: Option<String>,
    },
    SourceUnavailable {
        detail: Option<String>,
    },
    PeerOffline {
        detail: Option<String>,
    },
    VerificationFailed {
        attempts: u8,
        max_attempts: u8,
        detail: Option<String>,
    },
    Other {
        detail: String,
    },
}

impl DownloadFailure {
    pub(crate) fn from_error(error: impl Into<String>) -> Self {
        let error = error.into();
        let lower = error.to_ascii_lowercase();

        if lower.contains("permission denied") {
            return Self::PermissionDenied;
        }
        if lower.contains("file not found")
            || lower.contains("file missing")
            || lower.contains("no longer available on this device")
        {
            return Self::FileRemoved;
        }
        if lower.contains("version mismatch") {
            let current_version = lower
                .strip_prefix("version mismatch: server has version ")
                .and_then(|rest| rest.split_whitespace().next())
                .and_then(|n| n.parse::<u64>().ok());
            return Self::VersionMismatch {
                current_version,
                detail: Some(error),
            };
        }
        if lower.contains("file content changed") || lower.contains("changed since catalogue") {
            return Self::FileChanged {
                detail: Some(error),
            };
        }
        if lower.contains("temporarily unavailable") || lower.contains("file unavailable") {
            return Self::SourceUnavailable {
                detail: Some(error),
            };
        }
        if lower.contains("peer offline")
            || lower.contains("not currently reachable")
            || lower.contains("address unavailable")
            || lower.contains("connection failed")
            || lower.contains("relay unavailable")
        {
            return Self::PeerOffline {
                detail: Some(error),
            };
        }
        if lower.contains("verification failed")
            || lower.contains("hash mismatch")
            || lower.contains("size mismatch")
        {
            return Self::VerificationFailed {
                attempts: 1,
                max_attempts: 3,
                detail: Some(error),
            };
        }

        Self::Other { detail: error }
    }

    pub(crate) fn title(&self) -> &'static str {
        match self {
            Self::PermissionDenied => "Access denied",
            Self::FileRemoved => "File removed from device",
            Self::FileChanged { .. } => "File changed since catalogue",
            Self::VersionMismatch { .. } => "Version mismatch",
            Self::SourceUnavailable { .. } => "File temporarily unavailable",
            Self::PeerOffline { .. } => "Peer offline",
            Self::VerificationFailed { .. } => "Verification failed",
            Self::Other { .. } => "Download failed",
        }
    }

    pub(crate) fn message(&self) -> String {
        match self {
            Self::PermissionDenied => {
                "You do not have permission to download this file. The owner may have revoked access or blocked your account.".to_string()
            }
            Self::FileRemoved => {
                "The local copy of this file has been removed or is no longer available on this device.".to_string()
            }
            Self::FileChanged { detail } => {
                let mut msg = "The file content has changed since the catalogue was issued. The catalogue entry is stale.".to_string();
                if let Some(detail) = detail {
                    msg.push(' ');
                    msg.push_str(detail);
                }
                msg
            }
            Self::VersionMismatch {
                current_version,
                detail,
            } => {
                let mut msg = "The file was updated while the download was in progress. The requested version no longer matches the current version on the server.".to_string();
                if let Some(version) = current_version {
                    msg.push_str(&format!(" Server has version v{version}."));
                }
                if let Some(detail) = detail {
                    msg.push(' ');
                    msg.push_str(detail);
                }
                msg
            }
            Self::SourceUnavailable { detail } => {
                let mut msg = "The file is not currently available on the remote peer. The file object may have been removed or the peer's storage is not reachable.".to_string();
                if let Some(detail) = detail {
                    msg.push(' ');
                    msg.push_str(detail);
                }
                msg
            }
            Self::PeerOffline { detail } => {
                let mut msg = "The recipient peer is not currently reachable. They may be offline or behind a restrictive network.".to_string();
                if let Some(detail) = detail {
                    msg.push(' ');
                    msg.push_str(detail);
                }
                msg
            }
            Self::VerificationFailed {
                attempts,
                max_attempts,
                detail,
            } => {
                let mut msg = if *attempts >= *max_attempts {
                    format!(
                        "The downloaded file could not be verified after {max_attempts} attempts. Try again later."
                    )
                } else {
                    format!(
                        "The downloaded file was corrupted. Retrying… (attempt {attempts} of {max_attempts})"
                    )
                };
                if let Some(detail) = detail {
                    msg.push(' ');
                    msg.push_str(detail);
                }
                msg
            }
            Self::Other { detail } => detail.clone(),
        }
    }

    pub(crate) fn recovery_action(&self) -> &'static str {
        match self {
            Self::PermissionDenied => "Contact the file owner and ask them to grant access",
            Self::FileRemoved => "Re-download from a peer who still has a copy",
            Self::FileChanged { .. } => "Refresh the catalogue, then request the download again",
            Self::VersionMismatch { .. } => "Request a fresh download of the updated file",
            Self::SourceUnavailable { .. } => "Try again later, or contact the owner",
            Self::PeerOffline { .. } => "Wait for the peer to come online",
            Self::VerificationFailed { .. } => "Retry the download",
            Self::Other { .. } => "Try again",
        }
    }

    pub(crate) fn stability_label(&self) -> &'static str {
        match self {
            Self::SourceUnavailable { .. }
            | Self::PeerOffline { .. }
            | Self::VerificationFailed { .. } => "Temporary",
            Self::VersionMismatch { .. } => "Terminal",
            Self::PermissionDenied | Self::FileRemoved | Self::FileChanged { .. } => "Permanent",
            Self::Other { .. } => "Permanent",
        }
    }

    pub(crate) fn retry_available(&self) -> bool {
        matches!(
            self,
            Self::SourceUnavailable { .. }
                | Self::PeerOffline { .. }
                | Self::VerificationFailed { .. }
        )
    }

    pub(crate) fn diagnostics(&self) -> Option<String> {
        match self {
            Self::VersionMismatch { detail, .. }
            | Self::FileChanged { detail }
            | Self::SourceUnavailable { detail }
            | Self::PeerOffline { detail }
            | Self::VerificationFailed { detail, .. } => detail.clone(),
            Self::Other { detail } => Some(detail.clone()),
            Self::PermissionDenied | Self::FileRemoved => None,
        }
    }
}

#[derive(Clone, Debug, Hash, PartialEq, Eq)]
pub(crate) enum DownloadState {
    Ready {
        /// Total file size in bytes, if known ahead of time
        /// (e.g. provided in the FileShare message).  Carried
        /// forward into Active when the user clicks Download so
        /// the progress bar appears immediately.
        total: Option<u64>,
    },
    Active {
        bytes: u64,
        total: Option<u64>,
    },
    /// User-initiated pause — transfer suspended, can be resumed.
    /// Retains bytes/total so the progress bar can show a dimmed snapshot.
    Paused {
        bytes: u64,
        total: Option<u64>,
    },
    Completed {
        saved_name: String,
        saved_path: Option<std::path::PathBuf>,
        /// Total file size preserved from last Active state, if known.
        total_size: Option<u64>,
    },
    /// File was shared by the local user — the file resides at the given
    /// path and requires no download.  Rendered like Completed but without
    /// the green "download done" accent.
    Shared {
        name: String,
        path: std::path::PathBuf,
        size: Option<u64>,
    },
    Failed {
        failure: DownloadFailure,
    },
    Cancelled,
}

impl DownloadState {
    /// Returns true if this is a terminal state that should not be
    /// overwritten by late progress events.
    fn is_terminal(&self) -> bool {
        matches!(
            self,
            Self::Completed { .. } | Self::Shared { .. } | Self::Failed { .. } | Self::Cancelled
        )
    }
}

/// Download state tracked per file in the peer catalogue view.
#[derive(Clone, Debug)]
pub(crate) enum CatalogueDownloadState {
    /// Awaiting the async download task to start.
    Pending,
    /// Actively downloading with progress.
    Downloading {
        /// Bytes received so far.
        bytes: u64,
        /// Total expected bytes, if known.
        total: Option<u64>,
        /// Transfer speed in bytes/sec, updated periodically.
        speed: u64,
    },
    /// Download completed successfully — file is on disk.
    Completed {
        /// Filesystem path to the saved file.
        #[expect(dead_code)]
        path: PathBuf,
    },
    /// Download failed with an error message.
    Failed(String),
    /// Download was cancelled.
    #[expect(dead_code)]
    Cancelled,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub(crate) struct DownloadAttachment {
    pub(crate) kind: TransferKind,
    pub(crate) name: String,
    pub(crate) ticket: String,
    pub(crate) transfer_id: Option<TransferId>,
    pub(crate) state: DownloadState,
    /// Display name (or short public key) of the sending peer.
    pub(crate) source_peer: String,
    /// Current transfer speed in bytes per second, if known.
    pub(crate) speed_bytes_per_sec: Option<u64>,
    /// Optional video thumbnail (JPEG bytes) generated by the sender.
    pub(crate) thumbnail: Option<Vec<u8>>,
    /// Cached image handle for the thumbnail, created once to prevent flicker.
    pub(crate) thumbnail_handle: Option<iced::widget::image::Handle>,
    /// Hash of the thumbnail blob (for async fetch by receivers).
    pub(crate) thumbnail_hash: Option<MessageHash>,
    /// Poster dimensions preserve a known aspect ratio without probing video
    /// data from the view function.
    pub(crate) poster_dimensions: Option<(u32, u32)>,
    pub(crate) playback_error: Option<InlinePlaybackError>,
    /// Content identity extracted from the blob ticket; never inferred from
    /// the peer-controlled filename or MIME metadata.
    pub(crate) expected_content_hash: Option<String>,
}

impl std::hash::Hash for DownloadAttachment {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        self.kind.hash(state);
        self.name.hash(state);
        self.ticket.hash(state);
        self.transfer_id.hash(state);
        self.state.hash(state);
        self.source_peer.hash(state);
        self.speed_bytes_per_sec.hash(state);
        self.thumbnail.hash(state);
        // thumbnail_handle is a cached rendering artifact — not part of logical identity
        self.poster_dimensions.hash(state);
        self.playback_error.hash(state);
        self.expected_content_hash.hash(state);
    }
}

impl DownloadAttachment {
    pub(crate) fn new(
        kind: TransferKind,
        name: impl Into<String>,
        ticket: impl Into<String>,
        source_peer: impl Into<String>,
        thumbnail: Option<Vec<u8>>,
    ) -> Self {
        let ticket = ticket.into();
        let expected_content_hash = ticket
            .parse::<iroh_blobs::ticket::BlobTicket>()
            .ok()
            .map(|ticket| hex::encode(ticket.hash().as_bytes()));
        let poster_dimensions = thumbnail.as_deref().and_then(|bytes| {
            image::ImageReader::new(std::io::Cursor::new(bytes))
                .with_guessed_format()
                .ok()
                .and_then(|reader| reader.into_dimensions().ok())
        });
        Self {
            kind,
            name: name.into(),
            ticket,
            transfer_id: None,
            state: DownloadState::Ready { total: None },
            source_peer: source_peer.into(),
            speed_bytes_per_sec: None,
            thumbnail: thumbnail.clone(),
            thumbnail_handle: thumbnail
                .as_deref()
                .map(|bytes| iced::widget::image::Handle::from_bytes(bytes.to_vec())),
            thumbnail_hash: None,
            poster_dimensions,
            playback_error: None,
            expected_content_hash,
        }
    }

    fn total_bytes_label(bytes: u64) -> String {
        const UNITS: [&str; 5] = ["B", "KiB", "MiB", "GiB", "TiB"];
        let mut value = bytes as f64;
        let mut unit_idx = 0usize;
        while value >= 1024.0 && unit_idx < UNITS.len() - 1 {
            value /= 1024.0;
            unit_idx += 1;
        }
        if unit_idx == 0 {
            format!("{} {}", bytes, UNITS[unit_idx])
        } else {
            format!("{value:.1} {}", UNITS[unit_idx])
        }
    }

    #[expect(dead_code)]
    fn action_label(&self) -> &'static str {
        match self.state {
            DownloadState::Ready { .. } => "Download",
            DownloadState::Active { .. } => "Downloading",
            DownloadState::Paused { .. } => "Paused",
            DownloadState::Completed { .. } => "Open",
            DownloadState::Shared { .. } => "Open",
            DownloadState::Failed { ref failure } if failure.retry_available() => "Retry",
            DownloadState::Failed { .. } => "Dismiss",
            DownloadState::Cancelled => "Retry",
        }
    }

    #[expect(dead_code)]
    fn status_label(&self) -> String {
        match &self.state {
            DownloadState::Ready { .. } => "Ready to download".to_string(),
            DownloadState::Active {
                bytes,
                total: Some(total),
            } if *total > 0 => {
                let pct = ((*bytes as f64 / *total as f64) * 100.0).clamp(0.0, 100.0);
                format!(
                    "Downloading — {} / {} ({pct:.0}%)",
                    Self::total_bytes_label(*bytes),
                    Self::total_bytes_label(*total),
                )
            }
            DownloadState::Active { bytes, total: None } => {
                format!(
                    "Downloading — {} received (size unknown)",
                    Self::total_bytes_label(*bytes)
                )
            }
            DownloadState::Active {
                bytes,
                total: Some(total),
            } => format!(
                "Downloading — {} / {}",
                Self::total_bytes_label(*bytes),
                Self::total_bytes_label(*total)
            ),
            DownloadState::Completed {
                saved_name,
                saved_path,
                total_size,
            } => {
                let size_suffix = total_size
                    .filter(|s| *s > 0)
                    .map(|s| format!(" ({})", DownloadAttachment::total_bytes_label(s)))
                    .unwrap_or_default();
                if let Some(path) = saved_path {
                    format!("Saved — {}{size_suffix} ({})", saved_name, path.display())
                } else {
                    format!("Saved — {saved_name}{size_suffix}")
                }
            }
            DownloadState::Failed { failure } => {
                let mut lines = vec![format!("{} — {}", failure.title(), failure.message())];
                if let Some(detail) = failure.diagnostics() {
                    if !detail.is_empty() {
                        lines.push(detail);
                    }
                }
                lines.join(" ")
            }
            DownloadState::Paused { bytes, total } => {
                let size_info = total
                    .filter(|t| *t > 0)
                    .map(|t| {
                        format!(
                            " — {} / {}",
                            DownloadAttachment::total_bytes_label(*bytes),
                            DownloadAttachment::total_bytes_label(t)
                        )
                    })
                    .unwrap_or_else(|| {
                        format!(
                            " — {} received",
                            DownloadAttachment::total_bytes_label(*bytes)
                        )
                    });
                format!("Paused — tap Resume to continue{size_info}")
            }
            DownloadState::Cancelled => "Cancelled".to_string(),
            DownloadState::Shared { name, path, size } => {
                let size_suffix = size
                    .filter(|s| *s > 0)
                    .map(|s| format!(" ({})", DownloadAttachment::total_bytes_label(s)))
                    .unwrap_or_default();
                format!("Shared — {name}{size_suffix} ({})", path.display())
            }
        }
    }

    #[expect(dead_code)]
    fn progress_fraction(&self) -> Option<f32> {
        match self.state {
            DownloadState::Active {
                bytes,
                total: Some(total),
            } if total > 0 => Some((bytes as f32 / total as f32).clamp(0.0, 1.0)),
            DownloadState::Paused {
                bytes,
                total: Some(total),
            } if total > 0 => Some((bytes as f32 / total as f32).clamp(0.0, 1.0)),
            DownloadState::Paused { .. } => None,
            _ => None,
        }
    }

    #[expect(dead_code)]
    fn status_tone(&self) -> Color {
        match self.state {
            DownloadState::Ready { .. }
            | DownloadState::Active { .. }
            | DownloadState::Paused { .. } => accent_primary(&iced::Theme::Dark),
            DownloadState::Completed { .. } => Color::from_rgb(0.2, 0.7, 0.2),
            DownloadState::Shared { .. } => accent_primary(&iced::Theme::Dark),
            DownloadState::Failed { ref failure } => match failure.stability_label() {
                "Temporary" => Color::from_rgb(0.78, 0.58, 0.16),
                "Terminal" | "Permanent" => Color::from_rgb(0.8, 0.22, 0.22),
                _ => Color::from_rgb(0.8, 0.22, 0.22),
            },
            DownloadState::Cancelled => Color::from_rgb(0.55, 0.55, 0.55),
        }
    }

    fn estimated_height(&self) -> f32 {
        // Rows: title + action + spacing. Active adds progress + source rows.
        // Error state adds a failure-title, action, and detail rows.
        match self.state {
            DownloadState::Ready { .. } => 84.0,
            DownloadState::Active { total: Some(_), .. } | DownloadState::Paused { .. } => 112.0,
            DownloadState::Active { total: None, .. } => 176.0,
            DownloadState::Completed { .. } => 92.0,
            DownloadState::Shared { .. } => 92.0,
            DownloadState::Failed { .. } => 176.0,
            DownloadState::Cancelled => 84.0,
        }
    }
}

#[derive(Clone, Debug)]
pub struct ChatEntry {
    kind: ChatKind,
    label: String,
    body: String,
    /// Protocol message content hash, for edit/delete/reaction matching.
    message_hash: Option<MessageHash>,
    /// Whether this entry has been edited after initial delivery.
    edited: bool,
    /// Emoji reactions attached to this entry.
    reactions: Vec<String>,
    /// Cached formatted label text, e.g. \"[Alice]\" or \"[Alice ✓]\"
    /// Avoids format!() allocation on every render frame.
    label_text: Option<String>,
    /// Cached joined reaction emoji string, e.g. \"👍  ❤️\"
    /// Avoids reactions.join() allocation on every render frame.
    reactions_text: Option<String>,
    /// Cached formatted message timestamp, e.g. \"12:34\" or \"Mon 12:34\" or \"Jan 5\".
    /// Computed once from the UTC timestamp when the entry is created or its
    /// timestamp changes — avoids calling `format_message_time` on every frame.
    formatted_time: Option<String>,
    /// Cached iced image handle, decoded once at construction time.
    /// Cloning is cheap (Arc<..>) — avoids re-decoding JPEG bytes on every frame.
    image_handle: Option<iced::widget::image::Handle>,
    /// Cached iced handle for this entry's sender avatar (profile picture).
    /// Populated once in `entries_push` from `friend_image_handles` so the
    /// view function never does a per-frame HashMap lookup.
    avatar_handle: Option<iced::widget::image::Handle>,
    /// Compressed image bytes for inline rendering, if this is an image message.
    /// Kept for session-history/replay persistence; the `image_handle` is used
    /// during rendering to avoid re-decoding on every frame.
    image_bytes: Option<Vec<u8>>,
    /// Storage identifier returned by the [`ImageStore`] for this image.
    /// Relative path within the store's files root — never an absolute filesystem path.
    /// Set when the image is persisted via `ImageStore::save_image()`.
    image_identifier: Option<String>,
    /// Non-fatal rendering / persistence error to show inline with the image.
    image_error: Option<String>,
    /// Original image pixel width, extracted from image bytes at construction time.
    /// Used to compute the display size (scale-to-fit) during rendering.
    image_width: Option<u32>,
    /// Original image pixel height, extracted from image bytes at construction time.
    /// Used to compute the display size (scale-to-fit) during rendering.
    image_height: Option<u32>,
    /// Animated GIF frames (raw RGBA handles + per-frame delays) managed by
    /// the iced-moving-picture `Gif` widget. None for static images and
    /// single-frame GIFs (those render as static images).
    gif_frames: Option<std::sync::Arc<iced_moving_picture::widget::gif::Frames>>,
    /// Unix epoch milliseconds when this message was sent (protocol sent_at
    /// for remote messages, local creation time for system/local messages).
    timestamp: Option<i64>,
    /// Stable event id for delivery state tracking (0 = unassigned).
    event_id: u64,
    /// Current delivery state of this message (only meaningful for Local kind).
    delivery_state: DeliveryState,
    /// PublicKey of the sender (None for local/system messages).
    sender_key: Option<PublicKey>,
    /// Optional download attachment rendered alongside this entry.
    download: Option<DownloadAttachment>,
    /// Generation counter bumped on every mutation to this entry's visible
    /// content.  Used by the view-layer widget cache to detect stale cached
    /// elements: when the current entry's gen differs from the cached gen,
    /// the entry's widget tree is rebuilt.
    widget_gen: u64,
    /// Cached link preview data for URLs in this message body.
    /// Set asynchronously by the link preview fetcher.
    link_preview: Option<link_preview::LinkPreviewData>,
    /// True while a link preview fetch is in flight for this entry.
    link_preview_loading: bool,
    /// Whether a link preview fetch for this entry failed.
    link_preview_error: bool,
    /// Cached URL segments parsed from the message body.
    /// Computed once when the entry is created or body changes.
    /// Avoids calling `link_preview::parse_url_segments` on every render frame.
    parsed_segments: Option<Vec<link_preview::TextSegment>>,
}

/// Decode an animated GIF into iced-moving-picture `Frames` (raw RGBA
/// handles + per-frame delays). Returns None if the image is not a GIF or has
/// only one frame — single-frame GIFs render as static images.
fn decode_gif_frames(
    image_bytes: &[u8],
) -> Option<std::sync::Arc<iced_moving_picture::widget::gif::Frames>> {
    use image::codecs::gif::GifDecoder;
    use image::AnimationDecoder;
    use std::io::Cursor;

    // First pass: count frames. A single-frame GIF must stay on the static
    // image path — the Gif widget would otherwise keep requesting redraws
    // forever (its update loop re-schedules at the frame delay even when the
    // frame never changes).
    let decoder = GifDecoder::new(Cursor::new(image_bytes)).ok()?;
    let frame_count = decoder.into_frames().count();
    if frame_count <= 1 {
        return None;
    }

    // Second pass: decode once into raw RGBA handles. The widget advances
    // frames itself via per-frame delay + request_redraw_at, so there is no
    // PNG encode→decode cycle and no global tick.
    let frames = iced_moving_picture::widget::gif::Frames::from_bytes(image_bytes.to_vec()).ok()?;
    Some(std::sync::Arc::new(frames))
}

impl ChatEntry {
    fn system(text: impl Into<String>) -> Self {
        let mut s = Self {
            kind: ChatKind::System,
            label: "System".into(),
            body: sanitize_display_text(&text.into(), DEFAULT_MAX_DISPLAY_LENGTH),
            message_hash: None,
            edited: false,
            reactions: Vec::new(),
            image_handle: None,
            avatar_handle: None,
            image_bytes: None,
            image_identifier: None,
            image_error: None,
            image_width: None,
            image_height: None,
            gif_frames: None,
            timestamp: Some(now_ms()),
            event_id: 0,
            delivery_state: DeliveryState::default(),
            sender_key: None,
            download: None,
            widget_gen: 0,
            label_text: None,
            reactions_text: None,
            formatted_time: None,
            link_preview: None,
            link_preview_loading: false,
            link_preview_error: false,
            parsed_segments: None,
        };
        s.update_cache();
        s
    }
    fn local(label: impl Into<String>, text: impl Into<String>) -> Self {
        let label = sanitize_single_line(&label.into());
        let text = sanitize_display_text(&text.into(), DEFAULT_MAX_DISPLAY_LENGTH);
        Self {
            kind: ChatKind::Local,
            label,
            body: text,
            message_hash: None,
            edited: false,
            reactions: Vec::new(),
            image_handle: None,
            avatar_handle: None,
            image_bytes: None,
            image_identifier: None,
            image_error: None,
            image_width: None,
            image_height: None,
            gif_frames: None,
            timestamp: Some(now_ms()),
            event_id: 0,
            delivery_state: DeliveryState::default(),
            sender_key: None,
            download: None,
            widget_gen: 0,
            label_text: None,
            reactions_text: None,
            formatted_time: None,
            link_preview: None,
            link_preview_loading: false,
            link_preview_error: false,
            parsed_segments: None,
        }
    }
    fn remote(
        label: impl Into<String>,
        text: impl Into<String>,
        hash: Option<MessageHash>,
        sent_at_secs: Option<u64>,
        sender: Option<PublicKey>,
    ) -> Self {
        Self {
            kind: ChatKind::Remote,
            label: sanitize_single_line(&label.into()),
            body: sanitize_display_text(&text.into(), DEFAULT_MAX_DISPLAY_LENGTH),
            message_hash: hash,
            edited: false,
            reactions: Vec::new(),
            image_handle: None,
            avatar_handle: None,
            image_bytes: None,
            image_identifier: None,
            image_error: None,
            image_width: None,
            image_height: None,
            gif_frames: None,
            timestamp: sent_at_secs.map(|s| s as i64 * 1000),
            event_id: 0,
            delivery_state: DeliveryState::default(),
            sender_key: sender,
            download: None,
            widget_gen: 0,
            label_text: None,
            reactions_text: None,
            formatted_time: None,
            link_preview: None,
            link_preview_loading: false,
            link_preview_error: false,
            parsed_segments: None,
        }
    }

    #[expect(clippy::too_many_arguments)]
    fn image(
        kind: ChatKind,
        label: impl Into<String>,
        body: impl Into<String>,
        image_bytes: Vec<u8>,
        hash: Option<MessageHash>,
        sent_at_secs: Option<u64>,
        sender: Option<PublicKey>,
        image_identifier: Option<String>,
        image_error: Option<String>,
    ) -> Self {
        // Extract original image dimensions for scale-to-fit rendering.
        let (img_w, img_h) = {
            use std::io::Cursor;
            image::ImageReader::new(Cursor::new(&image_bytes))
                .with_guessed_format()
                .ok()
                .and_then(|r| r.into_dimensions().ok())
                .map(|(w, h)| (Some(w), Some(h)))
                .unwrap_or((None, None))
        };
        Self {
            kind,
            label: sanitize_single_line(&label.into()),
            body: sanitize_display_text(&body.into(), DEFAULT_MAX_DISPLAY_LENGTH),
            message_hash: hash,
            edited: false,
            reactions: Vec::new(),
            image_handle: Some(iced::widget::image::Handle::from_bytes(image_bytes.clone())),
            avatar_handle: None,
            image_bytes: Some(image_bytes.clone()), // Keep for session history/replay
            image_identifier,
            image_error,
            image_width: img_w,
            image_height: img_h,
            gif_frames: decode_gif_frames(&image_bytes),
            timestamp: sent_at_secs.map(|s| s as i64 * 1000),
            event_id: 0,
            delivery_state: DeliveryState::default(),
            sender_key: sender,
            download: None,
            widget_gen: 0,
            label_text: None,
            reactions_text: None,
            formatted_time: None,
            link_preview: None,
            link_preview_loading: false,
            link_preview_error: false,
            parsed_segments: None,
        }
    }

    fn system_download(
        text: impl Into<String>,
        kind: TransferKind,
        name: impl Into<String>,
        ticket: impl Into<String>,
        source_peer: impl Into<String>,
        thumbnail: Option<Vec<u8>>,
    ) -> Self {
        Self {
            kind: ChatKind::System,
            label: "System".into(),
            body: sanitize_display_text(&text.into(), DEFAULT_MAX_DISPLAY_LENGTH),
            message_hash: None,
            edited: false,
            reactions: Vec::new(),
            image_handle: None,
            avatar_handle: None,
            image_bytes: None,
            image_identifier: None,
            image_error: None,
            image_width: None,
            image_height: None,
            gif_frames: None,
            timestamp: Some(now_ms()),
            event_id: 0,
            delivery_state: DeliveryState::default(),
            sender_key: None,
            download: Some(DownloadAttachment::new(
                kind,
                name,
                ticket,
                source_peer,
                thumbnail,
            )),
            widget_gen: 0,
            label_text: None,
            reactions_text: None,
            formatted_time: None,
            link_preview: None,
            link_preview_loading: false,
            link_preview_error: false,
            parsed_segments: None,
        }
    }

    /// Returns true when conservative attachment classification identifies a video.
    fn is_video_file(name: &str) -> bool {
        classify_attachment(None, name) == MediaKind::Video
    }

    #[expect(dead_code)]
    fn estimated_height(&self) -> f32 {
        LayoutCache::compute_height(self, None, TYPO_SM)
    }

    /// Override the timestamp with a specific Unix epoch millisecond value.
    #[expect(dead_code)]
    fn with_timestamp(mut self, ms: Option<i64>) -> Self {
        self.timestamp = ms;
        self
    }

    /// Mark this entry's visible content as changed, invalidating any cached
    /// widget tree in the renderer.  Call this after every mutation to fields
    /// that affect the on-screen rendering (body, label, delivery_state,
    /// reactions, image_handle, image_error, etc.).
    fn bump_gen(&mut self) {
        self.widget_gen += 1;
        self.update_cache();
    }

    /// Recompute cached display strings used by the renderer.
    /// Call whenever label, delivery_state, or reactions change.
    fn update_cache(&mut self) {
        self.label_text = if matches!(self.kind, ChatKind::Local) && self.event_id > 0 {
            let icon = self.delivery_state.display_icon();
            // The Seen (eye) icon is intentionally omitted from the label
            // per UX spec — it adds visual noise without actionable value.
            if icon == "\u{1F441}" {
                Some(self.label.clone())
            } else {
                Some(format!("{} {}", self.label, icon))
            }
        } else {
            Some(self.label.clone())
        };
        self.reactions_text = if self.reactions.is_empty() {
            None
        } else {
            Some(self.reactions.join("  "))
        };
        self.parsed_segments = Some(link_preview::parse_url_segments(&self.body));
        // Cache the formatted timestamp once so the bubble metadata row never
        // re-formats on every frame.  `entries_push` calls `update_cache` for
        // every entry (live and replayed), so the timestamp always renders.
        self.formatted_time = self.timestamp.map(format_message_time);
    }
}

// ── Screen navigation ─────────────────────────────────────────────────

/// The active view in the main panel.
///
/// The sidebar (chat list, friends, requests) is always visible regardless
/// of the active screen — only the right-hand main panel changes.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Screen {
    /// No chat selected — empty state shown in the main panel.
    ChatList,
    /// File sharing dashboard — five-tab screen (see docs/file-sharing-guide.md).
    FileSharing,
    /// An individual chat room with a given topic.
    Chat { topic: TopicId },
    /// The friend request management screen.
    FriendRequests,
    /// Application settings screen.
    Settings,
    /// Peer profile overlay — shows shared files with Download buttons.
    PeerProfile(PublicKey),
    /// Remote file catalogue browsing — shows a peer's shared file catalogue.
    PeerCatalogue(PublicKey),
    /// Redesigned friend profile view with context menu and action buttons.
    FriendProfile(PublicKey),
    /// Public room directory — browse advertised rooms from the current relay.
    Discover,
    /// Group list — shows known groups and a create-group button.
    Groups,
    /// Embedded terminal tab (feature `terminal`).
    #[cfg(feature = "terminal")]
    Terminal,
    /// Developer component gallery — excluded from release navigation.
    Gallery,
}

// ── State-safety snapshots ─────────────────────────────────────────────

/// Atomic snapshot of the room a join was initiated for, captured when the
/// async subscription task is spawned. Mirrors telepathy's
/// `CallSlotSnapshot { state, direct_peer, generation }`: the `generation`
/// token is bumped on every room-join initiation, so a stale completion
/// (e.g. `RoomOpened` delivered for a room the user has since left or
/// switched away from) can be detected in debug builds before it clobbers
/// the newer room's state.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct RoomSnapshot {
    pub topic: TopicId,
    pub generation: u64,
}

// ── Per-conversation runtime state ─────────────────────────────────────

/// Runtime state for a single live conversation (active or background).
///
/// Each conversation has its own gossip subscription, forwarder task,
/// message entries, name cache, and composer state. Background
/// conversations keep their forwarder alive when the user switches to
/// another conversation — only the UI display swaps.
#[derive(Debug)]
pub struct ConversationLive {
    // ── Subscription ──
    /// Gossip message sender for this conversation.
    pub sender: Option<GossipSender>,
    /// Optional forward-handle; kept alive so background subscriptions
    /// continue to receive events.
    pub forward_handle: Option<n0_future::task::JoinHandle<()>>,
    /// Pending forwarder handle awaiting transfer.
    pub forward_handle_slot: Arc<StdMutex<Option<n0_future::task::JoinHandle<()>>>>,
    /// The gossip topic for this conversation.
    #[expect(dead_code)]
    pub topic: TopicId,
    /// Ticket string for sharing this conversation.
    pub ticket_str: String,

    // ── Chat state ──
    /// Chat messages for this conversation.
    pub entries: Vec<ChatEntry>,
    /// Composer input text.
    pub composer_text: String,
    /// Whether to auto-scroll to the latest message.
    pub follow_latest: bool,
    /// Name cache: peer PublicKey → display name.
    pub names: HashMap<PublicKey, String>,
    /// Maps content hash to stable event id for self-sent messages.
    pub self_sent_events: HashMap<MessageHash, u64>,
    /// Maintained indexes into this conversation's entries.
    pub event_id_to_index: HashMap<u64, usize>,
    pub message_hash_to_index: HashMap<MessageHash, usize>,
    /// Number of entries already saved to ChatHistoryStore.
    pub history_saved_count: usize,
    /// Cached layout for the chat log.
    #[expect(dead_code)]
    pub layout_cache: std::cell::RefCell<LayoutCache>,
    /// Y scroll offset.
    pub scroll_offset: f32,
    /// Viewport height.
    pub viewport_height: f32,
    /// Per-entry generation tracker for widget cache invalidation.
    /// Resized to match `entries` length on every mutation; a mismatch between
    /// `widget_gen[i]` and `self.entries[i].widget_gen` means the cached widget
    /// tree for entry `i` is stale.
    #[expect(dead_code)]
    pub entry_widget_gen: Vec<u64>,

    // ── Downloads ──
    /// Pending file download info: (filename, ticket_string).
    pub pending_file: Option<(String, String)>,
    /// Pending image downloads queue.
    pub pending_image: VecDeque<(String, MessageHash, PublicKey)>,
    /// Index of the chat entry with the active download.
    pub download_entry_index: Option<usize>,
    /// Transfer ID for the active download.
    pub active_download_transfer_id: Option<TransferId>,
    /// TransferId → entry index cache for O(1) progress update lookups.
    pub transfer_id_to_index: HashMap<TransferId, usize>,

    // ── Network peers ──
    /// Set of gossip neighbors for this conversation.
    pub neighbors: HashSet<PublicKey>,
    /// Whether this conversation has a usable gossip sender. True when
    /// subscribed AND the subscription has yielded a valid sender handle.
    /// Cleared when the conversation is left or re-subscription is needed.
    pub sender_ready: bool,
    /// Events received while this conversation is not selected.
    pub pending_events: VecDeque<NetEvent>,
    /// Number of unread events received while hidden.
    pub unread: u64,
    /// Whether persisted history has been loaded from ChatHistoryStore
    /// and replayed into this conversation's entries.
    pub history_loaded: bool,
}

impl ConversationLive {
    /// Create a new live conversation for the given topic.
    fn new(topic: TopicId) -> Self {
        Self {
            sender: None,
            sender_ready: false,
            forward_handle: None,
            forward_handle_slot: Arc::new(StdMutex::new(None)),
            topic,
            ticket_str: String::new(),
            entries: Vec::new(),
            composer_text: String::new(),
            follow_latest: true,
            names: HashMap::new(),
            self_sent_events: HashMap::new(),
            event_id_to_index: HashMap::new(),
            message_hash_to_index: HashMap::new(),
            history_saved_count: 0,
            layout_cache: std::cell::RefCell::new(LayoutCache::new(TYPO_SM)),
            scroll_offset: 0.0,
            viewport_height: 0.0,
            entry_widget_gen: Vec::new(),
            pending_file: None,
            pending_image: VecDeque::new(),
            download_entry_index: None,
            active_download_transfer_id: None,
            transfer_id_to_index: HashMap::new(),
            neighbors: HashSet::new(),
            pending_events: VecDeque::new(),
            unread: 0,
            history_loaded: false,
        }
    }

    /// Convenience: read the gossip sender, or `None` if not yet subscribed.
    #[expect(dead_code)]
    fn sender(&self) -> Option<&GossipSender> {
        self.sender.as_ref()
    }
}

